def pg(n):return 559 if n<=5 else 560 if n<=72 else 561
def add(n,st,steps,ans,ck,parts=[]):
 b.add(n,pg(n),('적분 전략','Strategy for integration'),st,steps,ans,parts=parts);b.verify(n,*ck);b.save()
def ma(n,eq,steps,ans,ck,parts=[]):add(n,(M(eq)+'적분을 구하라.',M(eq)+'Evaluate the integral.'),fs(*steps),same(M(ans)),ck,parts)
def core(f,F,q,steps,lo=None,hi=None,pts=None):
 f,F=s.sympify(f),s.sympify(F);ff=s.lambdify(q,f.subs({a:2,c:1,m:2}),'mpmath');FF=s.lambdify(q,F.subs({a:2,c:1,m:2}),'mpmath')
 for p in pts or ['.2','.4']:
  p=mp.mpf(str(p));assert abs(mp.diff(FF,p)-ff(p))<mp.mpf('1e-23')*max(1,abs(ff(p))),(f,F,p,mp.diff(FF,p),ff(p))
 out=list(steps)+fs('F('+s.latex(q)+')='+s.latex(F));I=s.Integral(f,q if lo is None else(q,lo,hi));ans=s.latex(F)+'+C'
 if lo is not None:
  val=s.simplify(F.subs(q,hi)-F.subs(q,lo));num=mp.quad(ff,[float(lo),float(hi)]);assert abs(complex(val.evalf())-complex(num))<1e-7*max(1,abs(complex(num))),(I,val,num)
  ans=s.latex(val);out+=fs(s.latex(I)+'=F('+s.latex(hi)+')-F('+s.latex(lo)+')='+ans)
 return I,out,ans
