add(70,(M(r'\int\frac{d\theta}{1+\cos^2\theta}')+'전체 실수축에서 가지의 연결을 고려하라.',M(r'\int\frac{d\theta}{1+\cos^2\theta}')+'Account for branch continuation on the real line.'),fs(r'u=\tan\theta,\quad d\theta=du/(1+u^2)',r'\int\frac{d\theta}{1+\cos^2\theta}=\int\frac{du}{u^2+2}=\frac1{\sqrt2}\arctan(u/\sqrt2)',r'k\pi-\pi/2<\theta<k\pi+\pi/2:\quad F(\theta)=\frac{\arctan(\tan\theta/\sqrt2)+k\pi}{\sqrt2}+C')+[('인접 구간 끝점에서는 연속인 극한값으로 정의한다. kπ 보정은 주값 arctan의 불필요한 점프를 없앤다.','At adjacent interval endpoints, use the continuous limiting value; the kπ adjustment removes the principal arctangent’s artificial jump.')],same(M(r'F(\theta)=\frac{\arctan(\tan\theta/\sqrt2)+k\pi}{\sqrt2}+C,\quad k\pi-\pi/2<\theta<k\pi+\pi/2')),('각 구간에서 도함수를 확인하고 양쪽 끝점 극한이 일치함을 확인했다.','Verified the derivative on each interval and matching limits at their boundaries.'))
add(89,(M(r'\int\sqrt{1-\sin x}\,dx')+'제곱근의 부호를 반영하여 구하라.',M(r'\int\sqrt{1-\sin x}\,dx')+'Evaluate with the correct radical sign.'),fs(r'1-\sin x=[\cos(x/2)-\sin(x/2)]^2',r'\sqrt{1-\sin x}=\sqrt2|\cos(x/2+\pi/4)|',r'\pi/2+2k\pi\le x\le\pi/2+2(k+1)\pi:\quad\operatorname{sgn}\cos(x/2+\pi/4)=(-1)^{k+1}',r'F(x)=2\sqrt2(-1)^{k+1}\sin(x/2+\pi/4)+4\sqrt2(k+1)+C'),same(M(r'F(x)=2\sqrt2(-1)^{k+1}\sin(x/2+\pi/4)+4\sqrt2(k+1)+C,\quad\pi/2+2k\pi\le x\le\pi/2+2(k+1)\pi')),('양쪽 구간에서 끝점 값이 같고 그곳에서 도함수도0이다. 절댓값을 버린 공식은 모든 실수에서 성립하지 않는다.','Adjacent endpoint values agree and the derivative is zero there. Dropping the absolute value would not be valid on the whole real line.'))
add(94,('F(x)=∫₀ˣexp(exp t)dt를 사용하여(a)∫₁²eˣ/x dx,(b)∫₂³dx/lnx를 나타내라.','With F(x)=∫₀ˣexp(exp t)dt, express(a)∫₁²eˣ/x dx and(b)∫₂³dx/lnx in terms of F.'),fs(r'(a)t=\ln x,\quad dx/x=dt,\quad x=e^t',r'\int_1^2\frac{e^x}x dx=\int_0^{\ln2}e^{e^t}dt=F(\ln2)',r'(b)t=\ln(\ln x),\quad x=e^{e^t},\quad dx=e^{e^t}e^tdt',r'\frac{dx}{\ln x}=e^{e^t}dt',r'\int_2^3\frac{dx}{\ln x}=F(\ln\ln3)-F(\ln\ln2)'),same(M(r'(a)F(\ln2);\quad(b)F(\ln\ln3)-F(\ln\ln2)')),('원 변수의 두 끝점을 변환했고 F(0)=0을 사용했다. 독립 수치적분으로 두 치환을 확인했다.','Transformed both original endpoints and used F(0)=0; independent numerical integration verifies both substitutions.'),['a','b'])
